CREATE TABLE "hives" (
    "id" INTEGER NOT NULL CONSTRAINT "PK_hives" PRIMARY KEY AUTOINCREMENT,
    "owner_id" INTEGER NOT NULL,
    "name" TEXT NOT NULL,
    "queen_year" INTEGER NOT NULL,
    "boxes" INTEGER NOT NULL,
    "yard_location" TEXT NULL,
    CONSTRAINT "FK_hives_users_owner_id" FOREIGN KEY ("owner_id") REFERENCES "users" ("id") ON DELETE CASCADE
);
CREATE TABLE "inspections" (
    "id" INTEGER NOT NULL CONSTRAINT "PK_inspections" PRIMARY KEY AUTOINCREMENT,
    "hive_id" INTEGER NOT NULL,
    "inspected_at" TEXT NOT NULL,
    "brood_frames" INTEGER NOT NULL,
    "temperament" INTEGER NOT NULL,
    "remarks" TEXT NULL,
    CONSTRAINT "FK_inspections_hives_hive_id" FOREIGN KEY ("hive_id") REFERENCES "hives" ("id") ON DELETE CASCADE
);
CREATE TABLE "lots" (
    "id" INTEGER NOT NULL CONSTRAINT "PK_lots" PRIMARY KEY AUTOINCREMENT,
    "owner_id" INTEGER NOT NULL,
    "label" TEXT NOT NULL,
    "weight_kg" REAL NOT NULL,
    "moisture_pct" REAL NOT NULL,
    "state" TEXT NOT NULL,
    "created_at" TEXT NOT NULL,
    "updated_at" TEXT NOT NULL,
    CONSTRAINT "FK_lots_users_owner_id" FOREIGN KEY ("owner_id") REFERENCES "users" ("id") ON DELETE CASCADE
);
CREATE TABLE "sessions" (
    "id" INTEGER NOT NULL CONSTRAINT "PK_sessions" PRIMARY KEY AUTOINCREMENT,
    "token" TEXT NOT NULL,
    "user_id" INTEGER NOT NULL,
    "expires_at" TEXT NOT NULL,
    CONSTRAINT "FK_sessions_users_user_id" FOREIGN KEY ("user_id") REFERENCES "users" ("id") ON DELETE CASCADE
);
CREATE TABLE "users" (
    "id" INTEGER NOT NULL CONSTRAINT "PK_users" PRIMARY KEY AUTOINCREMENT,
    "name" TEXT NOT NULL,
    "password" TEXT NOT NULL,
    "role" TEXT NOT NULL
);
CREATE UNIQUE INDEX "IX_hives_owner_id_name" ON "hives" ("owner_id", "name");
CREATE INDEX "IX_inspections_hive_id" ON "inspections" ("hive_id");
CREATE INDEX "IX_lots_owner_id" ON "lots" ("owner_id");
CREATE UNIQUE INDEX "IX_sessions_token" ON "sessions" ("token");
CREATE INDEX "IX_sessions_user_id" ON "sessions" ("user_id");
CREATE UNIQUE INDEX "IX_users_name" ON "users" ("name");

